#!/bin/bash
# ==============================================================================
# Wan2.2 Training Launch Script (DiffSynth-Studio)
# Model: Wan2.2-TI2V-5B (Text+Image-to-Video) with LoRA training
#
# This script trains on processed datasets prepared by wan22_prepare.py and
# extract_for_training.py. Data is in dataset/wan22_training/*_processed/
# Metadata CSVs are generated by scripts/convert_manifest_to_diffsynth.py
#
# Usage:
#   bash scripts/train_wan22.sh                    # Train on all datasets
#   bash scripts/train_wan22.sh --smoke            # Smoke test (5,476 samples)
#   bash scripts/train_wan22.sh --dataset hoigen1m # Single dataset
# ==============================================================================

set -euo pipefail

# ─── Configuration ───────────────────────────────────────────────────────────
PROJECT_ROOT="/srv/wm_teacher"
DIFFSYNTH_DIR="${PROJECT_ROOT}/DiffSynth-Studio"
cd "$DIFFSYNTH_DIR"

# Model
MODEL_ID="Wan-AI/Wan2.2-TI2V-5B"
MODEL_FILES="diffusion_pytorch_model*.safetensors,Wan-AI/Wan2.2-TI2V-5B:models_t5_umt5-xxl-enc-bf16.pth,Wan-AI/Wan2.2-TI2V-5B:Wan2.2_VAE.pth"
MODEL_CACHE="${PROJECT_ROOT}/models/Wan2.2-TI2V-5B"

# Training hyperparameters
LEARNING_RATE="1e-4"
NUM_EPOCHS="5"
LORA_RANK="32"
LORA_TARGET_MODULES="q,k,v,o,ffn.0,ffn.2"
LORA_BASE_MODEL="dit"
TASK="sft"

# Video config (Wan2.2 native resolution)
HEIGHT="704"
WIDTH="1280"
NUM_FRAMES="49"
DATASET_REPEAT="100"

# Output
OUTPUT_DIR="${PROJECT_ROOT}/models/train/Wan2.2-TI2V-5B_lora"

# Accelerate config
ACCELERATE_CONFIG="${PROJECT_ROOT}/training_metadata/accelerate_config.yaml"

# Logging
ENABLE_TENSORBOARD="true"
ENABLE_WANDB="false"
WANDB_PROJECT="wan22-training"

# ─── Proxy Settings ──────────────────────────────────────────────────────────
# Configure for HuggingFace model download if behind proxy
export HF_ENDPOINT="${HF_ENDPOINT:-https://huggingface.co}"
# Uncomment if needed:
# export HTTP_PROXY="http://proxy:port"
# export HTTPS_PROXY="http://proxy:port"
# export NO_PROXY="localhost,127.0.0.1"

# ─── Parse Arguments ─────────────────────────────────────────────────────────
MODE="full"
DATASET_FILTER=""

while [[ $# -gt 0 ]]; do
    case "$1" in
        --smoke)
            MODE="smoke"
            shift
            ;;
        --dataset)
            DATASET_FILTER="$2"
            shift 2
            ;;
        --learning-rate)
            LEARNING_RATE="$2"
            shift 2
            ;;
        --num-epochs)
            NUM_EPOCHS="$2"
            shift 2
            ;;
        --lora-rank)
            LORA_RANK="$2"
            shift 2
            ;;
        --output-dir)
            OUTPUT_DIR="$2"
            shift 2
            ;;
        *)
            echo "Unknown option: $1"
            echo "Usage: $0 [--smoke] [--dataset NAME] [--learning-rate LR] [--num-epochs N]"
            exit 1
            ;;
    esac
done

# ─── Prepare Training Data ───────────────────────────────────────────────────
echo "============================================"
echo "Step 1: Converting manifests to DiffSynth-Studio metadata CSV"
echo "============================================"

mkdir -p "${PROJECT_ROOT}/training_metadata"

if [ "$MODE" = "smoke" ]; then
    echo "Mode: SMOKE TEST (5,476 samples)"
    # Combine smoke HOIGen + Seamless metadata
    python3 "${PROJECT_ROOT}/scripts/convert_manifest_to_diffsynth.py" \
        --manifest "${PROJECT_ROOT}/dataset/smoke/hoigen_v1/manifest.jsonl" \
        --base-path "${PROJECT_ROOT}/dataset/smoke/hoigen_v1" \
        --output "${PROJECT_ROOT}/training_metadata/smoke_metadata.csv"
    TRAIN_METADATA="${PROJECT_ROOT}/training_metadata/smoke_metadata.csv"
    TRAIN_BASE_PATH="${PROJECT_ROOT}/dataset/smoke/hoigen_v1"
else
    if [ -n "$DATASET_FILTER" ]; then
        echo "Mode: SINGLE DATASET: $DATASET_FILTER"
        python3 "${PROJECT_ROOT}/scripts/convert_manifest_to_diffsynth.py" \
            --manifest "${PROJECT_ROOT}/dataset/wan22_training/${DATASET_FILTER}_processed/manifest.jsonl" \
            --base-path "${PROJECT_ROOT}/dataset/wan22_training/${DATASET_FILTER}_processed" \
            --output "${PROJECT_ROOT}/training_metadata/${DATASET_FILTER}_metadata.csv"
        TRAIN_METADATA="${PROJECT_ROOT}/training_metadata/${DATASET_FILTER}_metadata.csv"
        TRAIN_BASE_PATH="${PROJECT_ROOT}/dataset/wan22_training/${DATASET_FILTER}_processed"
    else
        echo "Mode: FULL TRAINING (all datasets: ${MODE})"
        # Combine all processed datasets into a single metadata CSV
        echo "Converting all datasets..."
        python3 "${PROJECT_ROOT}/scripts/convert_manifest_to_diffsynth.py" --all --output-dir "${PROJECT_ROOT}/training_metadata"

        # For multi-dataset training, use a combined approach
        # Since DiffSynth-Studio expects a single base_path + metadata pair,
        # we'll use hoigen1m as the starting dataset (largest single source)
        TRAIN_METADATA="${PROJECT_ROOT}/training_metadata/hoigen1m_metadata.csv"
        TRAIN_BASE_PATH="${PROJECT_ROOT}/dataset/wan22_training/hoigen1m_processed"
        echo "INFO: Training on hoigen1m dataset (106K samples)."
        echo "INFO: For multi-dataset training, run separate sessions per dataset."
    fi
fi

echo "Metadata: $TRAIN_METADATA"
echo "Base path: $TRAIN_BASE_PATH"

# Verify metadata exists
if [ ! -f "$TRAIN_METADATA" ]; then
    echo "ERROR: Metadata file not found: $TRAIN_METADATA"
    echo "Run convert_manifest_to_diffsynth.py first."
    exit 1
fi

# Count training samples
NUM_SAMPLES=$(wc -l < "$TRAIN_METADATA")
NUM_SAMPLES=$((NUM_SAMPLES - 1))  # Subtract header
echo "Training samples: $NUM_SAMPLES"

# ─── Download Model (if not cached) ──────────────────────────────────────────
echo ""
echo "============================================"
echo "Step 2: Checking/Caching Wan2.2-TI2V-5B model"
echo "============================================"

if [ -d "$MODEL_CACHE" ] && [ -f "${MODEL_CACHE}/diffusion_pytorch_model-00001-of-00006.safetensors" ]; then
    echo "Model already cached at: $MODEL_CACHE"
else
    echo "Downloading model from HuggingFace..."
    mkdir -p "$MODEL_CACHE"
    # Use huggingface-cli or modelscope for download
    if command -v modelscope &> /dev/null; then
        modelscope download --model "Wan-AI/Wan2.2-TI2V-5B" --local_dir "$MODEL_CACHE"
    elif command -v huggingface-cli &> /dev/null; then
        huggingface-cli download "Wan-AI/Wan2.2-TI2V-5B" --local-dir "$MODEL_CACHE"
    else
        echo "WARNING: Neither modelscope nor huggingface-cli found."
        echo "Please install: pip install modelscope huggingface_hub"
        echo "Then manually download: Wan-AI/Wan2.2-TI2V-5B"
        echo "To: $MODEL_CACHE"
    fi
fi

# ─── Training ────────────────────────────────────────────────────────────────
echo ""
echo "============================================"
echo "Step 3: Starting Wan2.2 LoRA Training"
echo "============================================"
echo "Model:      Wan2.2-TI2V-5B"
echo "Resolution: ${WIDTH}x${HEIGHT}"
echo "Frames:     ${NUM_FRAMES} (at 24fps = ~2s video)"
echo "LoRA rank:  ${LORA_RANK}"
echo "LR:         ${LEARNING_RATE}"
echo "Epochs:     ${NUM_EPOCHS}"
echo "Output:     ${OUTPUT_DIR}"
echo "Samples:    ${NUM_SAMPLES}"
echo "============================================"

# Generate accelerate config if not exists
if [ ! -f "$ACCELERATE_CONFIG" ]; then
    echo "Generating accelerate config..."
    accelerate config default \
        --mixed_precision bf16 \
        --num_processes 1 \
        --num_machines 1 \
        --machine_rank 0
fi

# Launch training
accelerate launch \
    --config_file "$ACCELERATE_CONFIG" \
    examples/wanvideo/model_training/train.py \
    --dataset_base_path "$TRAIN_BASE_PATH" \
    --dataset_metadata_path "$TRAIN_METADATA" \
    --height "$HEIGHT" \
    --width "$WIDTH" \
    --num_frames "$NUM_FRAMES" \
    --dataset_repeat "$DATASET_REPEAT" \
    --model_id_with_origin_paths "Wan-AI/Wan2.2-TI2V-5B:${MODEL_FILES}" \
    --learning_rate "$LEARNING_RATE" \
    --num_epochs "$NUM_EPOCHS" \
    --remove_prefix_in_ckpt "pipe.dit." \
    --output_path "$OUTPUT_DIR" \
    --lora_base_model "$LORA_BASE_MODEL" \
    --lora_target_modules "$LORA_TARGET_MODULES" \
    --lora_rank "$LORA_RANK" \
    --extra_inputs "input_image" \
    --use_gradient_checkpointing \
    --gradient_accumulation_steps 1 \
    --task "$TASK" \
    --enable_tensorboard_log

if [ "$ENABLE_WANDB" = "true" ]; then
    WANDB_ARGS="--enable_wandb_log --wandb_project $WANDB_PROJECT"
else
    WANDB_ARGS=""
fi

# Re-launch with conditional W&B
exec accelerate launch \
    --config_file "$ACCELERATE_CONFIG" \
    examples/wanvideo/model_training/train.py \
    --dataset_base_path "$TRAIN_BASE_PATH" \
    --dataset_metadata_path "$TRAIN_METADATA" \
    --height "$HEIGHT" \
    --width "$WIDTH" \
    --num_frames "$NUM_FRAMES" \
    --dataset_repeat "$DATASET_REPEAT" \
    --model_id_with_origin_paths "Wan-AI/Wan2.2-TI2V-5B:${MODEL_FILES}" \
    --learning_rate "$LEARNING_RATE" \
    --num_epochs "$NUM_EPOCHS" \
    --remove_prefix_in_ckpt "pipe.dit." \
    --output_path "$OUTPUT_DIR" \
    --lora_base_model "$LORA_BASE_MODEL" \
    --lora_target_modules "$LORA_TARGET_MODULES" \
    --lora_rank "$LORA_RANK" \
    --extra_inputs "input_image" \
    --use_gradient_checkpointing \
    --gradient_accumulation_steps 1 \
    --task "$TASK" \
    --enable_tensorboard_log \
    $WANDB_ARGS

echo ""
echo "============================================"
echo "Training complete!"
echo "Model saved to: $OUTPUT_DIR"
echo "============================================"
